    import * as stylex from '@stylexjs/stylex';
export const constants = {
  mediaQuery: "@media (min-width: 768px)"
};
export const vars = {
  bar: "var(--x1hi1hmf)",
  __varGroupHash__: "xop34xu"
};
    const viewTransition1 = stylex.viewTransitionClass({
      group: {
        transitionProperty: 'none',
      },
      imagePair: {
        borderRadius: 16,
      },
      old: {
        animationDuration: '0.5s',
      },
      new: {
        animationTimingFunction: 'ease-out',
      },
    });
    const fallback1 = stylex.positionTry({
      anchorName: '--myAnchor',
      positionArea: 'top left',
    });
    const fallback2 = stylex.positionTry({
      anchorName: '--otherAnchor',
      top: 'anchor(bottom)',
      insetInlineStart: 'anchor(start)',
    });
    const styles = stylex.create({
      root: {
        animationName: stylex.keyframes({
          from: {
            backgroundColor: 'yellow'
          },
          to: {
            backgroundColor: 'orange'
          },
        }),
        positionTryFallbacks: `${fallback1}, ${fallback2}`,
        color: {
          default: 'red',
          [constants.mediaQuery]: 'blue'
        },
        position: stylex.firstThatWorks('sticky', 'fixed')
      }
    });

    const theme = stylex.createTheme(vars, {
      bar: 'green'
    });

    stylex.props(styles.root, theme);

export const styles = stylex.create({
  root: {
    color: 'red'
  }
});

